import React, { createContext, useContext, useState } from 'react';

const AuthContext = createContext(null);

export const ROLES = {
  STUDENT: 'student',
  FACULTY: 'faculty',
  ADMIN: 'admin',
};

// Fake users for demo (in real app these come from backend/JWT)
export const DEMO_USERS = [
  { id: 1, name: 'Rahul Sharma',   email: 'rahul@college.edu',   password: 'student123', role: ROLES.STUDENT },
  { id: 2, name: 'Priya Das',      email: 'priya@college.edu',   password: 'student123', role: ROLES.STUDENT },
  { id: 3, name: 'Dr. A. Bose',    email: 'abose@college.edu',   password: 'faculty123', role: ROLES.FACULTY },
  { id: 4, name: 'Prof. S. Gupta', email: 'sgupta@college.edu',  password: 'faculty123', role: ROLES.FACULTY },
  { id: 5, name: 'Admin',          email: 'admin@college.edu',   password: 'admin123',   role: ROLES.ADMIN  },
];

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  const login = (email, password) => {
    const found = DEMO_USERS.find(u => u.email === email && u.password === password);
    if (found) { setUser(found); return { success: true }; }
    return { success: false, message: 'Invalid email or password.' };
  };

  const logout = () => setUser(null);

  const canEdit = user && (user.role === ROLES.ADMIN || user.role === ROLES.FACULTY);

  return (
    <AuthContext.Provider value={{ user, login, logout, canEdit }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
